namespace ALE.ACS.Engine.Core.Export;

/// <summary>
/// Represents an artifact generated by an export provider.
/// </summary>
public sealed class ExportArtifact
{
    /// <summary>
    /// Initializes a new instance of the <see cref="ExportArtifact"/> class.
    /// </summary>
    /// <param name="name">The artifact name.</param>
    /// <param name="extension">The artifact extension.</param>
    /// <param name="content">The artifact content.</param>
    /// <param name="encoding">The artifact encoding.</param>
    /// <param name="metadata">The artifact metadata.</param>
    public ExportArtifact(string name, string extension, string content, string encoding, IReadOnlyDictionary<string, string> metadata)
    {
        Name = name;
        Extension = extension;
        Content = content;
        Encoding = encoding;
        Metadata = metadata;
    }

    /// <summary>
    /// Gets the artifact name.
    /// </summary>
    public string Name { get; }

    /// <summary>
    /// Gets the artifact extension.
    /// </summary>
    public string Extension { get; }

    /// <summary>
    /// Gets the artifact content.
    /// </summary>
    public string Content { get; }

    /// <summary>
    /// Gets the artifact encoding.
    /// </summary>
    public string Encoding { get; }

    /// <summary>
    /// Gets the artifact metadata.
    /// </summary>
    public IReadOnlyDictionary<string, string> Metadata { get; }
}
